size_t i;
size_t fastest_idx = SIZE_MAX;
double max_abs_speed = -1.0;
double e = 0.0;
adcs_status_t st;

if ((wheels == NULL) || (momentum == NULL) || (momentum_norm == NULL) ||
    (energy == NULL) || (fastest == NULL)) {
    if (momentum != NULL) {
        *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
    if (momentum_norm != NULL) {
        *momentum_norm = 0.0;
    }
    if (energy != NULL) {
        *energy = 0.0;
    }
    if (fastest != NULL) {
        *fastest = SIZE_MAX;
    }
    return ADCS_E_NULL;
}

*momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
*momentum_norm = 0.0;
*energy = 0.0;
*fastest = SIZE_MAX;

if (count != 4U) {
    return ADCS_E_RANGE;
}

for (i = 0; i < count; i++) {
    adcs_vec3_t axis_norm;
    if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0) ||
        (!isfinite(wheels[i].speed_rad_s)) ||
        (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis_norm) != ADCS_OK)) {
        return ADCS_E_RANGE;
    }
}

st = adcs_wheel_momentum(wheels, count, momentum);
if (st != ADCS_OK) {
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    return ADCS_E_RANGE;
}

*momentum_norm = adcs_vec3_norm(momentum);

for (i = 0; i < count; i++) {
    double spd = wheels[i].speed_rad_s;
    e += 0.5 * wheels[i].inertia_kg_m2 * spd * spd;
}
*energy = e;

for (i = 0; i < count; i++) {
    double abs_speed = fabs(wheels[i].speed_rad_s);
    if (abs_speed > max_abs_speed) {
        max_abs_speed = abs_speed;
        fastest_idx = i;
    }
}
*fastest = fastest_idx;

return ADCS_OK;

